"summary": "Adjust liveness probe timeout and initial delay for new revision to accommodate startup time",
"hypotheses": [
    {
        "root_cause_class": "probe_too_strict_for_startup",
        "summary": "The new revision's liveness probe is failing during startup because its timeout is too short for the application's startup time.",
        "supporting": ["probe_kills", "killed_during_startup", "failure_onset_after_rollout", "prior_revision_was_healthy"],
