],
"proposal": {
    "capability": "deployment.set-probes",
    "target": {
        "group": "apps",
        "kind": "Deployment",
        "namespace": "edge",
        "name": "api-gateway",
        "uid": "uid-deployment-api-gateway"
    },
    "params": {
        "container": "app",
        "liveness": {
            "initialDelaySeconds": 30,
            "timeoutSeconds": 5
        }
    },
    "expected_effect": "The liveness probe will wait longer for the application to start and allow more time for the probe to succeed, preventing premature termination of the pod.",
    "rationale": "The liveness probe's timeout of 1 second is too short for the application's startup time, which takes at least 1 minute and 2 seconds. Increasing the timeout and initial delay will allow the application to start before the probe checks, preventing the probe from failing and terminating the pod.",
